def _generate_bagging_indices(random_state, bootstrap_features, bootstrap_samples, n_features, n_samples, max_features, max_samples, sample_weight):
    """Randomly draw feature and sample indices."""
    random_state = check_random_state(random_state)
    feature_indices = _generate_indices(random_state, bootstrap_features, n_features, max_features)
    if sample_weight is None:
        sample_indices = _generate_indices(random_state, bootstrap_samples, n_samples, max_samples)
    else:
        normalized_sample_weight = sample_weight / np.sum(sample_weight)
        sample_indices = random_state.choice(n_samples, max_samples, replace=bootstrap_samples, p=normalized_sample_weight)
    return (feature_indices, sample_indices)

