    U, Vt = svd_flip(U, Vt)
    components_ = Vt
    explained_variance_ = S ** 2 / (n_samples - 1)
    total_var = xp.sum(explained_variance_)
    explained_variance_ratio_ = explained_variance_ / total_var
    singular_values_ = xp.asarray(S, copy=True)
    if n_components == 'mle':
