    """Parse GML `lines` into a graph.
    """

    def tokenize():
        patterns = ['[A-Za-z][0-9A-Za-z_]*\\b', '[+-]?(?:[0-9]*\\.[0-9]+|[0-9]+\\.[0-9]*)(?:[Ee][+-]?[0-9]+)?', '[+-]?[0-9]+', '".*?"', '\\[', '\\]', '#.*$|\\s+']
        tokens = re.compile('|'.join((f'({pattern})' for pattern in patterns)))
        lineno = 0
        for line in lines:
            length = len(line)
            pos = 0
            while pos < length:
                match = tokens.match(line, pos)
                if match is None:
                    m = 'cannot tokenize %r at (%d, %d)'
                    raise NetworkXError(m % (line[pos:], lineno + 1, pos + 1))
                for i in range(len(patterns)):
                    group = match.group(i + 1)
                    if group is not None:
                        if i == 0:
                            value = group.rstrip()
                        elif i == 1:
                            value = float(group)
                        elif i == 2:
                            value = int(group)
                        else:
                            value = group
                        if i != 6:
                            yield Token(Pattern(i), value, lineno + 1, pos + 1)
                        pos += len(group)
                        break
            lineno += 1
        yield Token(None, None, lineno + 1, 1)

    def unexpected(curr_token, expected):
