    node: nodes.Expr
    if not vars_referenced and (not newstyle):
        singular = singular.replace('%%', '%')
        if plural:
            plural = plural.replace('%%', '%')
    func_name = 'gettext'
    func_args: t.List[nodes.Expr] = [nodes.Const(singular)]
    if context is not None:
        func_args.insert(0, nodes.Const(context))
