private boolean shiftComponentsUp(int startRow, int endRow) {
		int numComps = getNumComponents();
		if ((startRow > endRow) || startRow <= 0 || startRow >= numComps || endRow <= 0 ||
			endRow >= numComps) {
			return false;
		}
		DataTypeComponent comp = getComponent(startRow - 1);
