public RocCurve getRocCurve() {
    if (isExact) {
        INDArray pl = getProbAndLabelUsed();
        INDArray sorted = Nd4j.sortRows(pl, NUM, false);
        INDArray isPositive = sorted.getColumn(NUM);
        INDArray isNegative = sorted.getColumn(NUM).rsub(NUM);
        INDArray cumSumPos = isPositive.cumsum(-NUM);
        INDArray cumSumNeg = isNegative.cumsum(-NUM);
        int length = sorted.size(NUM);
        INDArray t = Nd4j.create(new int[] { length + NUM, NUM });
        t.put(new INDArrayIndex[] { NDArrayIndex.interval(NUM, length + NUM), NDArrayIndex.all() }, sorted.getColumn(NUM));
        INDArray fpr = Nd4j.create(new int[] { length + NUM, NUM });
        fpr.put(new INDArrayIndex[] { NDArrayIndex.interval(NUM, length + NUM), NDArrayIndex.all() }, cumSumNeg.div(countActualNegative));
        INDArray tpr = Nd4j.create(new int[] { length + NUM, NUM });
        tpr.put(new INDArrayIndex[] { NDArrayIndex.interval(NUM, length + NUM), NDArrayIndex.all() }, cumSumPos.div(countActualPositive));
        t.putScalar(NUM, NUM, NUM);
        fpr.putScalar(NUM, NUM, NUM);
        tpr.putScalar(NUM, NUM, NUM);
        fpr.putScalar(length + NUM, NUM, NUM);
        tpr.putScalar(length + NUM, NUM, NUM);
        double[] x_fpr_out = fpr.data().asDouble();
        double[] y_tpr_out = tpr.data().asDouble();
        double[] tOut = t.data().asDouble();
        if (rocRemoveRedundantPts) {
            double[][] temp = removeRedundant(tOut, x_fpr_out, y_tpr_out);
            tOut = temp[NUM];
            x_fpr_out = temp[NUM];
            y_tpr_out = temp[NUM];
        }
        return new RocCurve(tOut, x_fpr_out, y_tpr_out);
    } else {
        double[][] out = new double[NUM][thresholdSteps + NUM];
        int i = NUM;
        for (Map.Entry<Double, CountsForThreshold> entry : counts.entrySet()) {
            CountsForThreshold c = entry.getValue();
            double tpr = c.getCountTruePositive() / ((double) countActualPositive);
            double fpr = c.getCountFalsePositive() / ((double) countActualNegative);
            out[NUM][i] = c.getThreshold();
            out[NUM][i] = fpr;
            out[NUM][i] = tpr;
            i++;
        }
        return new RocCurve(out[NUM], out[NUM], out[NUM]);
    }
}

