    List<Long> toEvict = new ArrayList<Long>();
    EvictionPlan plan = new EvictionPlan(toMove, toEvict);
    StorageDir candidateDir = cascadingEvict(bytesToBeAvailable, location, plan);

    if (candidateDir == null) {
      return null;
