def set_positions(self, positions):
    """Update atomic positions but only for unconverged images."""
    n1 = 0
    for i, image in enumerate(self.images[1:-1]):
        if self.parallel:
            msg = 'Dynamic relaxation does not work efficiently when parallelizing over images. Try AutoNEB routine for freezing images in parallel.'
            raise ValueError(msg)
        forces_dyn = self._fmax_all()
        if forces_dyn[i] < self.fmax:
            n1 += self.natoms
        else:
            n2 = n1 + self.natoms
            image.set_positions(positions[n1:n2])
            n1 = n2

