        elif isinstance(interval, Interval):
            vals = S.EmptySet
            critical_values = S.EmptySet
            bounds = ((interval.left_open, interval.inf, '+'), (interval.right_open, interval.sup, '-'))
            for is_open, limit_point, direction in bounds:
