            sols = [get_gen_sol_from_part_sol(part_sols, a, x)]
    else:
        sols = [expr for expr, _ in sols]
    presol = [Eq(fx, riccati_inverse_normal(y, x, b1, b2, bp).cancel(extension=True)) for y in sols]
