        numer, denom = rewritten.as_numer_denom()
        if numer.as_poly(x, s) is None or denom.as_poly(x, s) is None:
            return None
        u = Dummy('u')
        sqrt_c0 = sqrt(c0)
        x_u = (u ** 2 - a0) / (b0 + 2 * sqrt_c0 * u)
