@staticmethod
def _caller_frame_info(offset: int, currentframe: Optional[Callable[[], Optional[FrameType]]]=None) -> Tuple[str, int, Dict[str, Any]]:
    """Get caller frame information.

        Args:
            offset (int): the caller offset within the current frame stack.
            currentframe (Callable[[], Optional[FrameType]], optional): the callable to use to
                retrieve the current frame. Defaults to None, which will use ``inspect.currentframe()``.

        Returns:
            Tuple[str, int, Dict[str, Any]]: A tuple containing the filename, the line number and
                the dictionary of local variables associated with the caller frame.

        Raises:
            RuntimeError: If the stack offset is invalid.
        """
    offset += 1
    if currentframe is None:
        import inspect
        frame = inspect.currentframe()
    else:
        frame = currentframe()
    if frame is not None:
        while offset and frame is not None:
            frame = frame.f_back
            offset -= 1
        assert frame is not None
        return (frame.f_code.co_filename, frame.f_lineno, frame.f_locals)
    else:
        from inspect import stack
        frame_info = stack()[offset]
        return (frame_info.filename, frame_info.lineno, frame_info.frame.f_locals)

