        double weightDiff = this.weight / other.weight;
        return walkDistance <= other.getWalkDistance() * 1.05
                && (weightDiff < 1.02 && this.weight - other.weight < 30)
                && this.getElapsedTimeSeconds() - other.getElapsedTimeSeconds() <= 30;
    }

